#[cfg(test)]
mod scratch {
    use super::*;

    #[test]
    fn scratch_replay() {
        let dir = std::path::Path::new("<job>/evidence");
        let records = Records::load_dir(dir).unwrap();
        let cases = replay_cases(&records, None);
        let mut refused = 0;
        let mut checked = 0;
        for c in &cases {
            let crit: Vec<&str> = c.reading.acceptance_criteria.iter().map(|x| x.text.as_str()).collect();
            let scores = coverage_scores(&c.request, &crit);
            let skip = c.reading.capability.is_none() || c.reading.question.is_some() || request_allows_split(&c.request);
            if !scores.is_empty() { checked += 1; }
            let mut bad = false;
            for (b, best, total) in &scores {
                let pct = best * 100 / total;
                println!("SCORE {} {}% ({}/{}) {}", c.job, pct, best, total, b.chars().take(70).collect::<String>());
                if pct < 40 { bad = true; }
            }
            if bad && !skip { refused += 1; println!("REFUSED {}", c.job); }
        }
        println!("REPLAY total={} with_bullets={} refused={}", cases.len(), checked, refused);
    }
}
EOF
